-- Generated by alchemists-tools probe (@COMMAND@).
-- Logs calls to game functions and changes nothing. Output: ue4ss/UE4SS.log, lines starting
-- with [@NAME@]. Ctrl + Numpad 9 logs how often each function has been called, and Ctrl + Numpad 8 what the
-- watched new objects hold.

local Library = require("AlchemistsLibrary")
local log = Library.logger("@NAME@")
local LIMIT = @LIMIT@  -- calls logged in full, per function

-- {path, params = {{name, type, layout}}}; params is nil for a Blueprint function (arguments logged unnamed)
local HOOKS = @HOOKS@

-- Classes whose new objects are logged
local NEW_OBJECTS = @NEW_OBJECTS@

local calls = {}

local function context_text(context)
    local ok, object = pcall(function() return context:get() end)
    if not ok then return "?" end
    local text = Library.describe(object)
    local has_owner, owner = pcall(function() return object:GetOwner() end)
    if has_owner and owner and owner:IsValid() then
        local row = Library.building_row(owner)
        text = text .. " (owner " .. owner:GetFName():ToString() .. (row and (", row " .. row) or "") .. ")"
        local authority = Library.has_authority(owner)
        if authority ~= nil then text = text .. (authority and ", has authority" or ", no authority") end
    end
    return text
end

local function arguments_text(hook, arguments)
    local parts = {}
    local count = hook.params and #hook.params or #arguments
    for i = 1, count do
        local ok, value = pcall(function() return arguments[i]:get() end)
        local param = hook.params and hook.params[i]
        local label = param and param.name or ("argument " .. i)
        parts[#parts + 1] = label .. " = " .. (ok and Library.describe(value, param and param.layout) or "?")
    end
    return table.concat(parts, "; ")
end

local hooked = {}

local function try_hook(hook)
    if hooked[hook.path] then return end
    local ok, error_message = pcall(RegisterHook, hook.path, function(context, ...)
        local arguments = {...}
        Library.safely(log, function()
            calls[hook.path] = (calls[hook.path] or 0) + 1
            if calls[hook.path] > LIMIT then return end
            log.log(string.format("%s call %d%s, on %s: %s", hook.path, calls[hook.path],
                calls[hook.path] == LIMIT and " (the last logged in full)" or "", context_text(context),
                arguments_text(hook, arguments)))
        end)
    end)
    if ok then
        hooked[hook.path] = true
        log.log("hooked " .. hook.path)
    else
        log.once("can't hook " .. hook.path .. " yet: " .. tostring(error_message))
    end
end

for _, hook in ipairs(HOOKS) do try_hook(hook) end
-- A Blueprint's functions exist only once it's loaded: try again until each is hooked
LoopInGameThreadWithDelay(2000, function()
    for _, hook in ipairs(HOOKS) do try_hook(hook) end
end)

-- New objects, newest last (at most 200), for Ctrl + Numpad 8
local new_objects = {}

for _, class in ipairs(NEW_OBJECTS) do
    NotifyOnNewObject(class, function(object)
        Library.safely(log, function()
            log.log("new " .. class .. ": " .. Library.describe(object))
            new_objects[#new_objects + 1] = object
            if #new_objects > 200 then table.remove(new_objects, 1) end
            -- Again a moment later, once it has been set up. Only light checks here: this runs while a world
            -- loads too, and reading containers then crashed the game (AlchemistsLibrary 0.2.0)
            ExecuteWithDelay(500, function()
                Library.on_game_thread(log, function()
                    if object:IsValid() then
                        log.log("   0.5 s later: " .. Library.describe(object) .. ", row "
                            .. tostring(Library.building_row(object)))
                    end
                end)
            end)
        end)
    end)
end

-- What the new objects hold: press once the world has loaded
Library.keybind(Key.NUM_EIGHT, {ModifierKey.CONTROL}, log, function()
    local shown = 0
    for i, object in ipairs(new_objects) do
        if object:IsValid() then
            local held = {}
            -- the newest object's lookup is reported step by step, to see why something holds nothing
            local report = i == #new_objects and function(line) log.log("   " .. line) end or nil
            for _, item in ipairs(Library.contents(object, report)) do
                held[#held + 1] = item.count .. " " .. item.name
            end
            log.log(Library.describe(object) .. " holds: " .. (#held > 0 and table.concat(held, ", ") or "nothing"))
            shown = shown + 1
        end
    end
    log.log(string.format("%d new object(s) still exist", shown))
end)

Library.keybind(Key.NUM_NINE, {ModifierKey.CONTROL}, log, function()
    for _, path in ipairs(Library.sorted_keys(calls)) do
        log.log(string.format("%s: %d call(s)", path, calls[path]))
    end
    if next(calls) == nil then log.log("no calls yet") end
end)

log.log(string.format("loaded: %d function(s), %d class(es) watched", #HOOKS, #NEW_OBJECTS))
